                { id: 'ev_eps_ally',   type: 'bonus',   threshold: 85, chance: 0.15, icon: '🤝', cost: 0,     repHit: -5 }
            ];
        }

        /* ------------------------------------------------------------------ */
        /* i18n helper — resolves through the framework when it is available,  */
        /* otherwise falls back to the adapter's own table.                    */
        /* ------------------------------------------------------------------ */
        _t(key, vars) {
            try {
                if (typeof window !== 'undefined' && window.mySimulation && window.mySimulation.t) {
                    var v = window.mySimulation.t(key, vars);
                    if (v !== undefined && v !== null && v !== key) return v;
                }
            } catch (e) { /* fall through */ }
            if (!this._trCache) this._trCache = this.getTranslations();
            var lang = 'en';
            try {
                if (typeof window !== 'undefined' && window.mySimulation && window.mySimulation.language) {
                    lang = String(window.mySimulation.language).split('-')[0].toLowerCase();
                } else if (typeof document !== 'undefined' && document.documentElement && document.documentElement.lang) {
                    lang = String(document.documentElement.lang).split('-')[0].toLowerCase();
                }
            } catch (e) { /* keep en */ }
            var dict = this._trCache[lang] || this._trCache.en;
            var s = (dict && dict[key] !== undefined) ? dict[key] : (this._trCache.en[key] !== undefined ? this._trCache.en[key] : key);
            if (vars) {
                for (var k in vars) { if (Object.prototype.hasOwnProperty.call(vars, k)) s = s.split('{' + k + '}').join(vars[k]); }
            }
            return s;
        }

        _money(v) { return '$' + Math.round(v).toLocaleString(); }

        get MIN_TOTAL_SPEND() { return this.MIN_REP + this.MIN_COMP + this.FIXED_COSTS; }

        /* ------------------------------------------------------------------ */
        initialize(state) {
            /* a fresh run, or an undo that popped the last history record: the
               framework calls initialize() again with a *dirty* domainState, so
               emptiness alone is not a sufficient test */
            var fresh = !state.domainState
                || Object.keys(state.domainState).length === 0
                || !state.history || state.history.length === 0;
            if (fresh) {
                state.domainState = {
                    cash: 500000,
                    debtInterestPaid: 0,
                    finesPaid: 0,
                    physicianAwareness: 10,
                    insuranceCoverage: 5,
                    complianceScore: 70,
                    reputation: 50,
                    totalPrescriptions: 0,
                    totalRevenue: 0,
                    totalProfit: 0,
                    insolvent: false,
                    revenueHistory: [],
                    profitHistory: [],
                    prescriptionHistory: [],
                    awarenessHistory: [],
                    coverageHistory: [],
                    complianceHistory: [],
                    scoreHistory: []
                };
                /* no score is displayed until a month has actually been played —
                   the KPI renders "—" rather than a plausible-looking number */
                state.domainState.score = null;
                state.domainState.performance = { overallScore: null };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    repBudget: 15000,
                    discountRate: 15,
                    complianceBudget: 5000
                };
            }
            this._updateGauges(state.domainState);
            this._updateEventBox(null);
        }

        /* ------------------------------------------------------------------ */
        validateDecisions(decisions) {
            var ui = (window.mySimulation && window.mySimulation.uiManager) ? window.mySimulation.uiManager : null;
            var warn = function(msg) { if (ui && ui.showNotification) ui.showNotification(msg, 'warning'); };

            var repInput = document.getElementById('repBudgetInput');
            if (repInput) decisions.repBudget = parseFloat(repInput.value);

            var discountInput = document.getElementById('discountInput');
            if (discountInput) decisions.discountRate = parseFloat(discountInput.value);

            var compInput = document.getElementById('complianceBudgetInput');
            if (compInput) decisions.complianceBudget = parseFloat(compInput.value);

            if (!isFinite(decisions.repBudget) || decisions.repBudget < this.MIN_REP || decisions.repBudget > this.MAX_REP) {
                warn(this._t('rep_warning')); return false;
            }
            if (!isFinite(decisions.discountRate) || decisions.discountRate < this.MIN_DISC || decisions.discountRate > this.MAX_DISC) {
                warn(this._t('discount_warning')); return false;
            }
            if (!isFinite(decisions.complianceBudget) || decisions.complianceBudget < this.MIN_COMP || decisions.complianceBudget > this.MAX_COMP) {
                warn(this._t('compliance_warning')); return false;
            }

            var ds = window.mySimulation.state.domainState;
            /* the full foreseeable outflow: the two budgets, fixed costs and the
               interest already owed on a negative balance */
            var interest = ds.cash < 0 ? Math.round(-ds.cash * this.INTEREST_RATE) : 0;
            var totalSpend = decisions.repBudget + decisions.complianceBudget + this.FIXED_COSTS + interest;
            var available = ds.cash + this.CREDIT_LINE;
            if (totalSpend > available) {
                warn(this._t('budget_warning', {
                    spend: this._money(totalSpend),
                    available: this._money(available),
                    credit: this._money(this.CREDIT_LINE),
                    floor: this._money(this.MIN_TOTAL_SPEND)
                }));
                return false;
            }
            return true;
        }

        /* ------------------------------------------------------------------ */
        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;

            /* interest is charged on the balance carried into the month */
            var interest = ds.cash < 0 ? Math.round(-ds.cash * this.INTEREST_RATE) : 0;

            /* --- physician awareness: a stock with monthly recall decay ------ */
            var awarenessGain = Math.sqrt(d.repBudget / 1000) * 2.8 * (1 - ds.physicianAwareness / 120);
            var awarenessLoss = ds.physicianAwareness * this.AWARENESS_DECAY;
            ds.physicianAwareness = Math.min(100, Math.max(0, ds.physicianAwareness + awarenessGain - awarenessLoss));

            /* --- EPS coverage: the discount is a *level*, so coverage seeks an
                   equilibrium implied by it instead of accumulating forever ---- */
            var discNorm = (d.discountRate - this.MIN_DISC) / (this.MAX_DISC - this.MIN_DISC);
            /* S-shaped response: a token discount buys almost no formulary position,
               the mid range buys most of it, and the last points buy very little —
               so neither the cheapest nor the deepest discount is the best play */
            var k = this.COVERAGE_HALF_SAT;
            var shaped = (discNorm * discNorm) / (discNorm * discNorm + k);
            var coverageTarget = 5 + 70 * shaped * (1 + k);
            if (ds.reputation > 60) coverageTarget *= 1 + ((ds.reputation - 60) / 100) * 0.5;
            if (ds.complianceScore < 50) coverageTarget *= 0.7;
            coverageTarget = Math.min(100, Math.max(0, coverageTarget));
            ds.insuranceCoverage = Math.min(100, Math.max(0,
                ds.insuranceCoverage + (coverageTarget - ds.insuranceCoverage) * this.COVERAGE_ADJUST));

            /* --- compliance: target-seeking on the compliance budget --------- */
            var complianceTarget = 40 + (d.complianceBudget / this.MAX_COMP) * 60;
            var complianceDelta = (complianceTarget - ds.complianceScore) * 0.3;
            ds.complianceScore = Math.min(100, Math.max(0, ds.complianceScore + complianceDelta));

            /* --- regulatory / partnership event ----------------------------- */
            var eventResult = this._checkEvents(ds);
            var fine = 0;
            if (eventResult) {
                fine = eventResult.cost;
                ds.reputation = Math.min(100, Math.max(0, ds.reputation - eventResult.repHit));
            }

            /* --- demand ------------------------------------------------------ */
            var awFactor = ds.physicianAwareness / 100;
            var covFactor = ds.insuranceCoverage / 100;
            var repFactor = 0.5 + (ds.reputation / 100) * 0.5;
            var seasonFactor = 1 + 0.1 * Math.sin((state.currentPeriod - 1) * Math.PI / 6);
            var noise = 0.9 + Math.random() * 0.2;

            var accessFactor = this.NO_COVERAGE_FLOOR + covFactor * (1 - this.NO_COVERAGE_FLOOR);
            var prescriptions = Math.round(this.BASE_DEMAND * awFactor * accessFactor * repFactor * seasonFactor * noise);
            prescriptions = Math.max(0, prescriptions);

            var effectivePrice = this.UNIT_PRICE * (1 - d.discountRate / 100);
            var revenue = Math.round(prescriptions * effectivePrice);

            /* every outflow that actually leaves the bank is inside totalCosts,
               so cash moves by exactly `profit` and the history reconciles */
            var operatingCosts = Math.round(d.repBudget + d.complianceBudget + this.FIXED_COSTS);
            var totalCosts = operatingCosts + fine + interest;
            var profit = revenue - totalCosts;

            ds.cash += profit;
            ds.finesPaid += fine;
            ds.debtInterestPaid += interest;
            ds.totalPrescriptions += prescriptions;
            ds.totalRevenue += revenue;
            ds.totalProfit += profit;
            ds.insolvent = ds.cash < 0;

            var repChange = 0;
            if (ds.complianceScore > 75) repChange += 1.5;
            if (ds.complianceScore < 50) repChange -= 2;
            if (prescriptions > 0.4 * this.BASE_DEMAND) repChange += 0.5;
            if (ds.insolvent) repChange -= 1;
            ds.reputation = Math.min(100, Math.max(0, ds.reputation + repChange));

            /* --- score: written EVERY period so express_extractHistory() and
                   express_resolveDomainScore() both find a real number -------- */
            var score = this._computeScore(ds);
            ds.score = score;
            ds.performance = this._performanceBlock(ds);

            ds.revenueHistory.push(revenue);
            ds.profitHistory.push(profit);
            ds.prescriptionHistory.push(prescriptions);
            ds.awarenessHistory.push(Math.round(ds.physicianAwareness));
            ds.coverageHistory.push(Math.round(ds.insuranceCoverage));
            ds.complianceHistory.push(Math.round(ds.complianceScore));
            ds.scoreHistory.push(score);

            var results = {
                period: state.currentPeriod,
                prescriptions: prescriptions,
                revenue: revenue,
                operatingCosts: operatingCosts,
                fine: fine,
                interest: interest,
                costs: totalCosts,
                profit: profit,
                awareness: Math.round(ds.physicianAwareness),
                coverage: Math.round(ds.insuranceCoverage),
                compliance: Math.round(ds.complianceScore),
                reputation: Math.round(ds.reputation),
                cash: ds.cash,
                insolvent: ds.insolvent,
                score: score,
                event: eventResult
            };

            this._updateGauges(ds);
            this._updateEventBox(eventResult);
            this._showResultsPanel(results);

            return results;
        }

        /* ------------------------------------------------------------------ */
        _computeScore(ds) {
            var reach = ((ds.physicianAwareness / 100) * 0.5 + (ds.insuranceCoverage / 100) * 0.5) * this.W_REACH;
            var comp  = Math.max(0, Math.min(1, (ds.complianceScore - 40) / 50)) * this.W_COMPLIANCE;
            var rep   = Math.max(0, Math.min(1, (ds.reputation - 30) / 55)) * this.W_REPUTATION;
            var prof  = Math.max(0, Math.min(1,
                (ds.totalProfit - this.PROFIT_FLOOR) / (this.PROFIT_CEIL - this.PROFIT_FLOOR))) * this.W_PROFIT;
            var solv  = ds.cash >= 0 ? this.W_SOLVENCY
                                     : Math.max(0, this.W_SOLVENCY * (1 + ds.cash / this.CREDIT_LINE));
            var total = reach + comp + rep + prof + solv;
            return Math.round(Math.max(0, Math.min(100, total)) * 10) / 10;
        }

        _performanceBlock(ds) {
            var reach = ((ds.physicianAwareness / 100) * 0.5 + (ds.insuranceCoverage / 100) * 0.5) * this.W_REACH;
            var comp  = Math.max(0, Math.min(1, (ds.complianceScore - 40) / 50)) * this.W_COMPLIANCE;
            var rep   = Math.max(0, Math.min(1, (ds.reputation - 30) / 55)) * this.W_REPUTATION;
            var prof  = Math.max(0, Math.min(1,
                (ds.totalProfit - this.PROFIT_FLOOR) / (this.PROFIT_CEIL - this.PROFIT_FLOOR))) * this.W_PROFIT;
            var solv  = ds.cash >= 0 ? this.W_SOLVENCY
                                     : Math.max(0, this.W_SOLVENCY * (1 + ds.cash / this.CREDIT_LINE));
            var r1 = function(x) { return Math.round(x * 10) / 10; };
            return {
                overallScore: this._computeScore(ds),
                marketReach: r1(reach),
                compliance: r1(comp),
                reputation: r1(rep),
                profitability: r1(prof),
                solvency: r1(solv)
            };
        }

        _band(score) {
            if (score >= 80) return 'perf_excellent';
            if (score >= 62) return 'perf_good';
            if (score >= 42) return 'perf_developing';
            return 'perf_needs_improvement';
        }

