        /* ------------------------------------------------------------------ */
        getPerformanceSummary(history) {
            if (!history.length) return {};
            var profits = history.map(function(r) { return r.results ? r.results.profit || 0 : 0; });
            var rxTotals = history.map(function(r) { return r.results ? r.results.prescriptions || 0 : 0; });
            var totalProfit = profits.reduce(function(s, p) { return s + p; }, 0);
            var totalRx = rxTotals.reduce(function(s, p) { return s + p; }, 0);
            var avgProfit = totalProfit / profits.length;

            var lastRecord = history[history.length - 1];
            var lastRes = lastRecord.results || {};
            var lastDs = lastRecord.domainState || {};
            var finalAwareness = lastRes.awareness || 0;
            var finalCoverage = lastRes.coverage || 0;
            var finalCompliance = lastRes.compliance || 0;
            var finalReputation = lastRes.reputation || 0;
            var finalCash = (lastRes.cash != null) ? lastRes.cash : 0;
            var totalFines = lastDs.finesPaid || 0;
            var totalInterest = lastDs.debtInterestPaid || 0;

            /* the headline number is the same composite the grader reads */
            var score = (lastDs.performance && lastDs.performance.overallScore != null)
                ? lastDs.performance.overallScore
                : (lastRes.score != null ? lastRes.score : 0);
            var components = lastDs.performance || {};
            var performance = this._t(this._band(score));

            var insights = [];
            if (finalCompliance < 60) insights.push(this._t('insight_compliance_low'));
            if (finalAwareness < 45) insights.push(this._t('insight_awareness_low'));
            if (finalCoverage < 30) insights.push(this._t('insight_coverage_low'));
            if (totalProfit < 0) insights.push(this._t('insight_unprofitable'));
            if (finalCash < 0) insights.push(this._t('insight_insolvent', { interest: this._money(totalInterest) }));
            if (totalFines > 0) insights.push(this._t('insight_fines', { fines: this._money(totalFines) }));
            if (finalReputation > 70 && finalCompliance > 75) insights.push(this._t('insight_reputation_strong'));
            if (totalProfit > 0 && finalCompliance > 75) insights.push(this._t('insight_profitable_compliant'));
            if (score >= 80) insights.push(this._t('insight_outstanding'));
            if (!insights.length) insights.push(this._t('insight_balanced'));

            return {
                totalProfit: totalProfit,
                totalPrescriptions: totalRx,
                avgMonthlyProfit: Math.round(avgProfit),
                finalAwareness: finalAwareness,
                finalCoverage: finalCoverage,
                finalCompliance: finalCompliance,
                finalReputation: finalReputation,
                finalCash: Math.round(finalCash),
                totalFines: totalFines,
                totalInterest: totalInterest,
                performance: performance,
                score: score,
                scoreComponents: components,
                insights: insights
            };
        }

        /* ------------------------------------------------------------------ */
        getHint(state, results) {
            var ds = state.domainState;
            /* ordered by how urgent and how actionable, most specific first —
               no branch above is unconditionally true, so every hint is reachable */
            if (ds.cash < 0) {
                return this._t('hint_insolvent', { debt: this._money(-ds.cash), rate: (this.INTEREST_RATE * 100).toFixed(0) });
            }
            if (ds.complianceScore < 50) return this._t('hint_compliance_low');
            if (ds.cash < 2 * this.MIN_TOTAL_SPEND) {
                return this._t('hint_budget_critical', { cash: this._money(ds.cash), floor: this._money(this.MIN_TOTAL_SPEND) });
            }
            if (results.profit < 0 && state.currentPeriod >= 5) return this._t('hint_loss');
            if (ds.physicianAwareness < 35 && state.currentPeriod > 3) return this._t('hint_awareness_low');
            if (ds.insuranceCoverage < 20 && state.currentPeriod > 4) return this._t('hint_coverage_low');
            if (results.profit > 0 && ds.complianceScore > 70) return this._t('hint_good');
            return this._t('hint_ramping');
        }

