        /* ------------------------------------------------------------------ */
        _checkEvents(ds) {
            for (var i = 0; i < this.EVENTS.length; i++) {
                var ev = this.EVENTS[i];
                if (ev.type === 'penalty' && ds.complianceScore < ev.threshold && Math.random() < ev.chance) return ev;
                if (ev.type === 'bonus' && ds.complianceScore > ev.threshold && Math.random() < ev.chance) return ev;
            }
            return null;
        }

        _setBar(barId, value) {
            var bar = document.getElementById(barId);
            if (!bar) return;
            var v = Math.round(value);
            bar.style.width = v + '%';
            bar.setAttribute('aria-valuenow', v);
            bar.setAttribute('aria-valuetext', v + '%');
        }

        _updateGauges(ds) {
            this._setBar('awarenessBar', ds.physicianAwareness);
            var awVal = document.getElementById('awarenessDisplay');
            if (awVal) awVal.textContent = Math.round(ds.physicianAwareness) + '%';

            this._setBar('coverageBar', ds.insuranceCoverage);
            var covVal = document.getElementById('coverageDisplay');
            if (covVal) covVal.textContent = Math.round(ds.insuranceCoverage) + '%';

            var compBadge = document.getElementById('complianceDisplay');
            if (compBadge) compBadge.textContent = Math.round(ds.complianceScore);

            var scoreEl = document.getElementById('scoreDisplay');
            if (scoreEl) {
                scoreEl.textContent = (ds.performance && ds.performance.overallScore != null)
                    ? Math.round(ds.performance.overallScore * 10) / 10 : '—';
            }

            var cashCard = document.getElementById('cashCard');
            if (cashCard) {
                if (ds.cash < 0) cashCard.classList.add('pharma-sim-kpi-negative');
                else cashCard.classList.remove('pharma-sim-kpi-negative');
            }
        }

        _updateEventBox(eventResult) {
            var box = document.getElementById('eventBox');
            if (!box) return;
            if (!eventResult) {
                box.style.display = 'none';
                return;
            }
            box.style.display = 'flex';
            var iconEl = document.getElementById('eventIcon');
            var textEl = document.getElementById('eventText');
            if (iconEl) iconEl.textContent = eventResult.icon;
            if (textEl) textEl.textContent = this._t(eventResult.id);

            box.classList.remove('pharma-sim-event-penalty', 'pharma-sim-event-bonus');
            box.classList.add(eventResult.type === 'penalty'
                ? 'pharma-sim-event-penalty' : 'pharma-sim-event-bonus');
        }

        _showResultsPanel(results) {
            var panel = document.getElementById('resultsPanel');
            if (panel) panel.style.display = 'block';

            var set = function(id, text, colour) {
                var el = document.getElementById(id);
                if (!el) return;
                el.textContent = text;
                if (colour) el.style.color = colour;
            };
            set('monthRxDisplay', results.prescriptions.toLocaleString());
            set('monthRevenueDisplay', '$' + results.revenue.toLocaleString());
            set('monthCostsDisplay', '$' + results.costs.toLocaleString());
            set('monthFinesDisplay', '$' + (results.fine + results.interest).toLocaleString(),
                (results.fine + results.interest) > 0 ? '#c0392b' : '');
            set('monthProfitDisplay', '$' + results.profit.toLocaleString(),
                results.profit >= 0 ? '#27ae60' : '#c0392b');
            set('monthCashDisplay', '$' + Math.round(results.cash).toLocaleString(),
                results.cash >= 0 ? '' : '#c0392b');
        }
    }

